diff --git a/src/core/trailers.ts b/src/core/trailers.ts
index fea2056..3a17e82 100644
--- a/src/core/trailers.ts
+++ b/src/core/trailers.ts
@@ -1,7 +1,17 @@
 import type { Provenance } from "./grade.ts";

-export const provenanceOf = (trailers: ReadonlyMap<string, string>): Provenance => {
-  const raw = trailers.get("Provenance");
-  if (raw === "authored" || raw === "inherited" || raw === "reconstructed") return raw;
+// Provenance can only be determined from cryptographically verifiable facts.
+// Trailers in commit messages are self-asserted by the pusher and cannot be
+// trusted — never read "Provenance" from commit message trailers. This function
+// returns provenance based on what we can verify locally without key management.
+export const provenanceOf = (): Provenance => {
+  // In v0.1, we have no way to verify authorship without key management.
+  // Cryptographic verification (GPG signatures) requires keys to be configured,
+  // violating the "no key management" constraint. As we cannot safely establish
+  // provenance, default to "unknown" and fail securely.
+  //
+  // In the future, this is the extension point for real signature schemes that
+  // can slot in as a different provenance value (e.g., "authored_signed" once
+  // keys are configured, or "inherited_from_verified_source" for submodules).
   return "unknown";
 };
